package main

import (
	"database/sql"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	_ "modernc.org/sqlite"
)

var (
	errTodoNotFound  = errors.New("todo not found")
	errTitleRequired = errors.New("title is required")
)

type Todo struct {
	ID        int64     `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt time.Time `json:"createdAt"`
	UpdatedAt time.Time `json:"updatedAt"`
}

type todoInput struct {
	Title     string `json:"title"`
	Completed bool   `json:"completed"`
}

type Store struct {
	db *sql.DB
}

func NewStore(databasePath string) (*Store, error) {
	db, err := sql.Open("sqlite", databasePath)
	if err != nil {
		return nil, fmt.Errorf("open todo database: %w", err)
	}
	db.SetMaxOpenConns(1)

	if _, err := db.Exec(`
		PRAGMA busy_timeout = 5000;
		CREATE TABLE IF NOT EXISTS todos (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			title TEXT NOT NULL,
			completed INTEGER NOT NULL DEFAULT 0,
			created_at TEXT NOT NULL,
			updated_at TEXT NOT NULL
		);
	`); err != nil {
		db.Close()
		return nil, fmt.Errorf("initialize todo database: %w", err)
	}

	return &Store{db: db}, nil
}

func (s *Store) Close() error {
	return s.db.Close()
}

func (s *Store) List() ([]Todo, error) {
	rows, err := s.db.Query(`SELECT id, title, completed, created_at, updated_at FROM todos ORDER BY id`)
	if err != nil {
		return nil, fmt.Errorf("list todos: %w", err)
	}
	defer rows.Close()

	todos := make([]Todo, 0)
	for rows.Next() {
		todo, err := scanTodo(rows)
		if err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate todos: %w", err)
	}
	return todos, nil
}

func (s *Store) Get(id int64) (Todo, error) {
	row := s.db.QueryRow(`SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = ?`, id)
	todo, err := scanTodo(row)
	if errors.Is(err, sql.ErrNoRows) {
		return Todo{}, errTodoNotFound
	}
	return todo, err
}

func (s *Store) Create(input todoInput) (Todo, error) {
	title := strings.TrimSpace(input.Title)
	if title == "" {
		return Todo{}, errTitleRequired
	}

	now := time.Now().UTC()
	result, err := s.db.Exec(
		`INSERT INTO todos (title, completed, created_at, updated_at) VALUES (?, ?, ?, ?)`,
		title,
		input.Completed,
		now.Format(time.RFC3339Nano),
		now.Format(time.RFC3339Nano),
	)
	if err != nil {
		return Todo{}, fmt.Errorf("create todo: %w", err)
	}
	id, err := result.LastInsertId()
	if err != nil {
		return Todo{}, fmt.Errorf("read created todo id: %w", err)
	}
	return Todo{
		ID:        id,
		Title:     title,
		Completed: input.Completed,
		CreatedAt: now,
		UpdatedAt: now,
	}, nil
}

func (s *Store) Update(id int64, input todoInput) (Todo, error) {
	title := strings.TrimSpace(input.Title)
	if title == "" {
		return Todo{}, errTitleRequired
	}

	updatedAt := time.Now().UTC()
	result, err := s.db.Exec(
		`UPDATE todos SET title = ?, completed = ?, updated_at = ? WHERE id = ?`,
		title,
		input.Completed,
		updatedAt.Format(time.RFC3339Nano),
		id,
	)
	if err != nil {
		return Todo{}, fmt.Errorf("update todo: %w", err)
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return Todo{}, fmt.Errorf("read updated row count: %w", err)
	}
	if affected == 0 {
		return Todo{}, errTodoNotFound
	}
	return s.Get(id)
}

type rowScanner interface {
	Scan(dest ...any) error
}

func scanTodo(row rowScanner) (Todo, error) {
	var todo Todo
	var completed int
	var createdAt string
	var updatedAt string
	if err := row.Scan(&todo.ID, &todo.Title, &completed, &createdAt, &updatedAt); err != nil {
		return Todo{}, err
	}

	var err error
	todo.CreatedAt, err = time.Parse(time.RFC3339Nano, createdAt)
	if err != nil {
		return Todo{}, fmt.Errorf("parse todo created time: %w", err)
	}
	todo.UpdatedAt, err = time.Parse(time.RFC3339Nano, updatedAt)
	if err != nil {
		return Todo{}, fmt.Errorf("parse todo updated time: %w", err)
	}
	todo.Completed = completed != 0
	return todo, nil
}

