package main

import (
	"database/sql"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"time"

	_ "modernc.org/sqlite"
)

var (
	errTodoNotFound  = errors.New("todo not found")
	errTitleRequired = errors.New("title is required")
)

type Todo struct {
	ID        int64     `json:"id"`
	Title     string    `json:"title"`
	Completed bool      `json:"completed"`
	CreatedAt time.Time `json:"createdAt"`
	UpdatedAt time.Time `json:"updatedAt"`
}

type todoInput struct {
	Title     string `json:"title"`
	Completed bool   `json:"completed"`
}

type Store struct {
	db *sql.DB
}

func NewStore(databasePath string) (*Store, error) {
	db, err := sql.Open("sqlite", databasePath)
	if err != nil {
		return nil, fmt.Errorf("open todo database: %w", err)
	}
	db.SetMaxOpenConns(1)

	if _, err := db.Exec(`
		PRAGMA busy_timeout = 5000;
		CREATE TABLE IF NOT EXISTS todos (
			id INTEGER PRIMARY KEY AUTOINCREMENT,
			title TEXT NOT NULL,
			completed INTEGER NOT NULL DEFAULT 0,
			created_at TEXT NOT NULL,
			updated_at TEXT NOT NULL
		);
	`); err != nil {
		db.Close()
		return nil, fmt.Errorf("initialize todo database: %w", err)
	}

	return &Store{db: db}, nil
}

func (s *Store) Close() error {
	return s.db.Close()
}

func (s *Store) List() ([]Todo, error) {
	rows, err := s.db.Query(`SELECT id, title, completed, created_at, updated_at FROM todos ORDER BY id`)
	if err != nil {
		return nil, fmt.Errorf("list todos: %w", err)
	}
	defer rows.Close()

	todos := make([]Todo, 0)
	for rows.Next() {
		todo, err := scanTodo(rows)
		if err != nil {
			return nil, err
		}
		todos = append(todos, todo)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("iterate todos: %w", err)
	}
	return todos, nil
}

func (s *Store) Get(id int64) (Todo, error) {
	row := s.db.QueryRow(`SELECT id, title, completed, created_at, updated_at FROM todos WHERE id = ?`, id)
	todo, err := scanTodo(row)
	if errors.Is(err, sql.ErrNoRows) {
		return Todo{}, errTodoNotFound
	}
	return todo, err
}

func (s *Store) Create(input todoInput) (Todo, error) {
	title := strings.TrimSpace(input.Title)
	if title == "" {
		return Todo{}, errTitleRequired
	}

	now := time.Now().UTC()
	result, err := s.db.Exec(
		`INSERT INTO todos (title, completed, created_at, updated_at) VALUES (?, ?, ?, ?)`,
		title,
		input.Completed,
		now.Format(time.RFC3339Nano),
		now.Format(time.RFC3339Nano),
	)
	if err != nil {
		return Todo{}, fmt.Errorf("create todo: %w", err)
	}
	id, err := result.LastInsertId()
	if err != nil {
		return Todo{}, fmt.Errorf("read created todo id: %w", err)
	}
	return Todo{
		ID:        id,
		Title:     title,
		Completed: input.Completed,
		CreatedAt: now,
		UpdatedAt: now,
	}, nil
}

func (s *Store) Update(id int64, input todoInput) (Todo, error) {
	title := strings.TrimSpace(input.Title)
	if title == "" {
		return Todo{}, errTitleRequired
	}

	updatedAt := time.Now().UTC()
	result, err := s.db.Exec(
		`UPDATE todos SET title = ?, completed = ?, updated_at = ? WHERE id = ?`,
		title,
		input.Completed,
		updatedAt.Format(time.RFC3339Nano),
		id,
	)
	if err != nil {
		return Todo{}, fmt.Errorf("update todo: %w", err)
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return Todo{}, fmt.Errorf("read updated row count: %w", err)
	}
	if affected == 0 {
		return Todo{}, errTodoNotFound
	}
	return s.Get(id)
}

func (s *Store) Delete(id int64) error {
	result, err := s.db.Exec(`DELETE FROM todos WHERE id = ?`, id)
	if err != nil {
		return fmt.Errorf("delete todo: %w", err)
	}
	affected, err := result.RowsAffected()
	if err != nil {
		return fmt.Errorf("read deleted row count: %w", err)
	}
	if affected == 0 {
		return errTodoNotFound
	}
	return nil
}

type rowScanner interface {
	Scan(dest ...any) error
}

func scanTodo(row rowScanner) (Todo, error) {
	var todo Todo
	var completed int
	var createdAt string
	var updatedAt string
	if err := row.Scan(&todo.ID, &todo.Title, &completed, &createdAt, &updatedAt); err != nil {
		return Todo{}, err
	}

	var err error
	todo.CreatedAt, err = time.Parse(time.RFC3339Nano, createdAt)
	if err != nil {
		return Todo{}, fmt.Errorf("parse todo created time: %w", err)
	}
	todo.UpdatedAt, err = time.Parse(time.RFC3339Nano, updatedAt)
	if err != nil {
		return Todo{}, fmt.Errorf("parse todo updated time: %w", err)
	}
	todo.Completed = completed != 0
	return todo, nil
}

func newAPIHandler(store *Store) http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /api/todos", func(w http.ResponseWriter, _ *http.Request) {
		todos, err := store.List()
		if err != nil {
			writeError(w, http.StatusInternalServerError, "could not list todos")
			return
		}
		writeJSON(w, http.StatusOK, todos)
	})
	mux.HandleFunc("GET /api/todos/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, ok := readID(w, r)
		if !ok {
			return
		}
		todo, err := store.Get(id)
		if err != nil {
			writeError(w, http.StatusNotFound, err.Error())
			return
		}
		writeJSON(w, http.StatusOK, todo)
	})
	mux.HandleFunc("POST /api/todos", func(w http.ResponseWriter, r *http.Request) {
		var input todoInput
		if !readJSON(w, r, &input) {
			return
		}
		todo, err := store.Create(input)
		if err != nil {
			writeError(w, http.StatusBadRequest, err.Error())
			return
		}
		writeJSON(w, http.StatusCreated, todo)
	})
	mux.HandleFunc("PUT /api/todos/{id}", func(w http.ResponseWriter, r *http.Request) {
		id, ok := readID(w, r)
		if !ok {
			return
		}
		var input todoInput
		if !readJSON(w, r, &input) {
			return
		}
		todo, err := store.Update(id, input)
		if errors.Is(err, errTodoNotFound) {
			writeError(w, http.StatusNotFound, err.Error())
			return
		}
		if err != nil {
			writeError(w, http.StatusBadRequest, err.Error())
			return
		}
		writeJSON(w, http.StatusOK, todo)
	})
	return mux
}

func newAppHandler(store *Store, frontendDir string) http.Handler {
	api := newAPIHandler(store)
	static := http.FileServer(http.Dir(frontendDir))

	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if strings.HasPrefix(r.URL.Path, "/api/") {
			api.ServeHTTP(w, r)
			return
		}

		requestedPath := filepath.Join(frontendDir, filepath.Clean(r.URL.Path))
		if r.URL.Path == "/" {
			requestedPath = filepath.Join(frontendDir, "index.html")
		}
		if _, err := os.Stat(requestedPath); err != nil {
			http.ServeFile(w, r, filepath.Join(frontendDir, "index.html"))
			return
		}
		static.ServeHTTP(w, r)
	})
}

func readID(w http.ResponseWriter, r *http.Request) (int64, bool) {
	id, err := strconv.ParseInt(r.PathValue("id"), 10, 64)
	if err != nil || id < 1 {
		writeError(w, http.StatusBadRequest, "invalid todo id")
		return 0, false
	}
	return id, true
}

func readJSON(w http.ResponseWriter, r *http.Request, destination any) bool {
	decoder := json.NewDecoder(http.MaxBytesReader(w, r.Body, 1<<20))
	decoder.DisallowUnknownFields()
	if err := decoder.Decode(destination); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body")
		return false
	}
	return true
}

func writeJSON(w http.ResponseWriter, status int, value any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	if err := json.NewEncoder(w).Encode(value); err != nil {
		log.Printf("encode response: %v", err)
	}
}

func writeError(w http.ResponseWriter, status int, message string) {
	writeJSON(w, status, map[string]string{"error": message})
}

func main() {
	port := flag.Int("port", 8080, "HTTP port")
	frontendDir := flag.String("frontend-dir", "frontend/dist", "built frontend directory")
	databasePath := flag.String("database", "data/todos.db", "SQLite database path")
	flag.Parse()

	if err := os.MkdirAll(filepath.Dir(*databasePath), 0o755); err != nil {
		log.Fatalf("create database directory: %v", err)
	}
	store, err := NewStore(*databasePath)
	if err != nil {
		log.Fatal(err)
	}
	defer store.Close()

	address := fmt.Sprintf(":%d", *port)
	log.Printf("todo app listening on http://localhost%s", address)
	if err := http.ListenAndServe(address, newAppHandler(store, *frontendDir)); err != nil {
		log.Fatal(err)
	}
}

